```python
def int_to_string(n):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    chars = []
    while n > 0:
        n, rem = divmod(n, 10)
        chars.append(chr(ord('0') + rem))
    return sign + "".join(reversed(chars))
```

