    """Returns the largest and smallest values from a list."""
    if not nums:
        return None, None
    maximum = nums[0]
    minimum = nums[0]
    for n in nums:
        if n > maximum:
            maximum = n
        if n < minimum:
            minimum = n
    return maximum, minimum
