def permutations(n):
    if n == 0:
        return [[]]
    def permute(nums):
        if not nums:
            return [[]]
        res = []
        for i in range(len(nums)):
            rest = nums[:i] + nums[i+1:]
            for p in permute(rest):
                res.append([nums[i]] + p)
        return res
    return permute(list(range(1, n+1)))
